import sys
import json
import numpy as np
import pandas as pd

def to_float(x):
    return round(float(x), 2)

def pct(x):
    return round(float(x), 1)

def safe_val(x, digits=2):
    if x is None or (isinstance(x, float) and np.isnan(x)):
        return None
    return round(float(x), digits)

def main():
    path = sys.argv[1]
    df = pd.read_csv(path)

    facts = []

    # Totals
    rev_tw = df['Revenue_TW'].sum(skipna=True)
    rev_lw = df['Revenue_LW'].sum(skipna=True)
    rev_ly = df['Revenue_LY'].sum(skipna=True)
    units_tw = df['Units_TW'].sum(skipna=True)
    units_lw = df['Units_LW'].sum(skipna=True)
    orders_tw = df['Orders_TW'].sum(skipna=True)
    orders_lw = df['Orders_LW'].sum(skipna=True)

    facts.append({
        "entity": "TOTAL", "metric": "revenue", "period": "TW",
        "value": to_float(rev_tw),
        "formula": "sum(Revenue_TW)"
    })
    facts.append({
        "entity": "TOTAL", "metric": "revenue", "period": "LW",
        "value": to_float(rev_lw),
        "formula": "sum(Revenue_LW)"
    })
    if not np.isnan(rev_ly) and rev_ly != 0:
        facts.append({
            "entity": "TOTAL", "metric": "revenue", "period": "LY",
            "value": to_float(rev_ly),
            "formula": "sum(Revenue_LY)"
        })

    facts.append({
        "entity": "TOTAL", "metric": "units", "period": "TW",
        "value": to_float(units_tw),
        "formula": "sum(Units_TW)"
    })
    facts.append({
        "entity": "TOTAL", "metric": "units", "period": "LW",
        "value": to_float(units_lw),
        "formula": "sum(Units_LW)"
    })
    facts.append({
        "entity": "TOTAL", "metric": "orders", "period": "TW",
        "value": to_float(orders_tw),
        "formula": "sum(Orders_TW)"
    })
    facts.append({
        "entity": "TOTAL", "metric": "orders", "period": "LW",
        "value": to_float(orders_lw),
        "formula": "sum(Orders_LW)"
    })

    if rev_lw and not np.isnan(rev_lw) and rev_lw != 0:
        wow_total = (rev_tw - rev_lw) / rev_lw * 100
        facts.append({
            "entity": "TOTAL", "metric": "revenue", "period": "WoW",
            "value": pct(wow_total),
            "formula": "(sum(Revenue_TW) - sum(Revenue_LW)) / sum(Revenue_LW) * 100"
        })

    if rev_ly and not np.isnan(rev_ly) and rev_ly != 0:
        yoy_total = (rev_tw - rev_ly) / rev_ly * 100
        facts.append({
            "entity": "TOTAL", "metric": "revenue", "period": "YoY",
            "value": pct(yoy_total),
            "formula": "(sum(Revenue_TW) - sum(Revenue_LY)) / sum(Revenue_LY) * 100"
        })

    # Top entities by revenue (Rank)
    top_rank = df.dropna(subset=['Rank']).sort_values('Rank').head(3)
    for _, row in top_rank.iterrows():
        if not np.isnan(row['Revenue_TW']):
            facts.append({
                "entity": row['Entity'], "metric": "revenue", "period": "TW",
                "value": to_float(row['Revenue_TW']),
                "formula": "Revenue_TW for top-ranked entity"
            })
        if not np.isnan(row['Share_Pct']):
            facts.append({
                "entity": row['Entity'], "metric": "share", "period": "TW",
                "value": pct(row['Share_Pct']),
                "formula": "Share_Pct of total TW revenue"
            })

    # Top entity by rank explicitly
    if not top_rank.empty:
        top_row = top_rank.iloc[0]
        facts.append({
            "entity": top_row['Entity'], "metric": "rank", "period": "TW",
            "value": to_float(top_row['Rank']),
            "formula": "Rank by Revenue_TW (1 = highest)"
        })

    # Biggest WoW gainer / decliner
    wow_df = df.dropna(subset=['WoW_Pct'])
    if not wow_df.empty:
        gainer = wow_df.loc[wow_df['WoW_Pct'].idxmax()]
        decliner = wow_df.loc[wow_df['WoW_Pct'].idxmin()]
        facts.append({
            "entity": gainer['Entity'], "metric": "revenue", "period": "WoW",
            "value": pct(gainer['WoW_Pct']),
            "formula": "(Revenue_TW - Revenue_LW) / Revenue_LW * 100 (max among entities)"
        })
        facts.append({
            "entity": decliner['Entity'], "metric": "revenue", "period": "WoW",
            "value": pct(decliner['WoW_Pct']),
            "formula": "(Revenue_TW - Revenue_LW) / Revenue_LW * 100 (min among entities)"
        })

    # Biggest YoY gainer / decliner
    yoy_df = df.dropna(subset=['YoY_Pct'])
    if not yoy_df.empty:
        gainer_y = yoy_df.loc[yoy_df['YoY_Pct'].idxmax()]
        decliner_y = yoy_df.loc[yoy_df['YoY_Pct'].idxmin()]
        facts.append({
            "entity": gainer_y['Entity'], "metric": "revenue", "period": "YoY",
            "value": pct(gainer_y['YoY_Pct']),
            "formula": "(Revenue_TW - Revenue_LY) / Revenue_LY * 100 (max among entities)"
        })
        facts.append({
            "entity": decliner_y['Entity'], "metric": "revenue", "period": "YoY",
            "value": pct(decliner_y['YoY_Pct']),
            "formula": "(Revenue_TW - Revenue_LY) / Revenue_LY * 100 (min among entities)"
        })

    # Highest share entity
    share_df = df.dropna(subset=['Share_Pct'])
    if not share_df.empty:
        top_share = share_df.loc[share_df['Share_Pct'].idxmax()]
        facts.append({
            "entity": top_share['Entity'], "metric": "share", "period": "TW",
            "value": pct(top_share['Share_Pct']),
            "formula": "Share_Pct of total TW revenue (max among entities)"
        })

    # Highest units TW
    units_df = df.dropna(subset=['Units_TW'])
    if not units_df.empty:
        top_units = units_df.loc[units_df['Units_TW'].idxmax()]
        facts.append({
            "entity": top_units['Entity'], "metric": "units", "period": "TW",
            "value": to_float(top_units['Units_TW']),
            "formula": "Units_TW (max among entities)"
        })

    # Highest orders TW
    orders_df = df.dropna(subset=['Orders_TW'])
    if not orders_df.empty:
        top_orders = orders_df.loc[orders_df['Orders_TW'].idxmax()]
        facts.append({
            "entity": top_orders['Entity'], "metric": "orders", "period": "TW",
            "value": to_float(top_orders['Orders_TW']),
            "formula": "Orders_TW (max among entities)"
        })

    # Biggest absolute revenue drop WoW
    df_abs_wow = df.dropna(subset=['Revenue_TW', 'Revenue_LW']).copy()
    if not df_abs_wow.empty:
        df_abs_wow['abs_change'] = df_abs_wow['Revenue_TW'] - df_abs_wow['Revenue_LW']
        biggest_drop = df_abs_wow.loc[df_abs_wow['abs_change'].idxmin()]
        biggest_gain = df_abs_wow.loc[df_abs_wow['abs_change'].idxmax()]
        facts.append({
            "entity": biggest_drop['Entity'], "metric": "revenue", "period": "WoW",
            "value": to_float(biggest_drop['abs_change']),
            "formula": "Revenue_TW - Revenue_LW (most negative among entities)"
        })
        facts.append({
            "entity": biggest_gain['Entity'], "metric": "revenue", "period": "WoW",
            "value": to_float(biggest_gain['abs_change']),
            "formula": "Revenue_TW - Revenue_LW (most positive among entities)"
        })

    # Biggest absolute revenue change YoY
    df_abs_yoy = df.dropna(subset=['Revenue_TW', 'Revenue_LY']).copy()
    if not df_abs_yoy.empty:
        df_abs_yoy['abs_change'] = df_abs_yoy['Revenue_TW'] - df_abs_yoy['Revenue_LY']
        biggest_drop_y = df_abs_yoy.loc[df_abs_yoy['abs_change'].idxmin()]
        biggest_gain_y = df_abs_yoy.loc[df_abs_yoy['abs_change'].idxmax()]
        facts.append({
            "entity": biggest_drop_y['Entity'], "metric": "revenue", "period": "YoY",
            "value": to_float(biggest_drop_y['abs_change']),
            "formula": "Revenue_TW - Revenue_LY (most negative among entities)"
        })
        facts.append({
            "entity": biggest_gain_y['Entity'], "metric": "revenue", "period": "YoY",
            "value": to_float(biggest_gain_y['abs_change']),
            "formula": "Revenue_TW - Revenue_LY (most positive among entities)"
        })

    # Number of entities
    facts.append({
        "entity": "TOTAL", "metric": "units", "period": "TW",
        "value": to_float(df['Entity'].nunique()),
        "formula": "count(distinct Entity)"
    })

    # Trim to 25 facts
    facts = facts[:25]

    print(json.dumps(facts))

if __name__ == "__main__":
    main()
